import { createHash } from "node:crypto";
import mongoose from "mongoose";
import { Notification } from "../../models/notification.model.js";
import { getNotificationNamespace } from "../../socket/index.js";
import { redis } from "../../config/redis.js";

const trimSeen = async (recipient) => {
    const seen = await Notification.find({ recipient, seen: true })
        .sort({ createdAt: -1 }).select("_id").skip(15).lean();
    if (seen.length) await Notification.deleteMany({ _id: { $in: seen.map((item) => item._id) } });
};

const chatNotificationId = (recipient, sender) => new mongoose.Types.ObjectId(
    createHash("sha256").update(`${recipient}:${sender}`).digest("hex").slice(0, 24)
);

export const NotificationService = {
    async create({ recipient, actor = null, type, payload = {} }) {
        if (type === "friend_chat" && payload.senderId) {
            const existing = await Notification.findOne({
                recipient,
                type,
                "payload.senderId": String(payload.senderId)
            }).sort({ createdAt: -1 });

            if (existing) {
            if (existing.seen || existing.seenAt) {
                existing.seen = false;
                existing.seenAt = null;
                existing.createdAt = new Date();   // bubble to top of list
                existing.payload = { ...existing.payload, ...payload };
                await existing.save();
                try {
                    getNotificationNamespace()
                        .to(String(recipient))
                        .emit("notification:new", existing.toObject());
                } catch { /* best effort */ }
            }
            return existing;
        }

            const _id = chatNotificationId(recipient, payload.senderId);
            let result;
            try {
                result = await Notification.updateOne(
                    { _id },
                    { $setOnInsert: { _id, recipient, actor, type, payload } },
                    { upsert: true }
                );
            } catch (error) {
                if (error?.code !== 11000) throw error;
            }
            const notification = await Notification.findById(_id);
            if (!notification) throw new Error("Chat notification could not be persisted.");
            if (!result?.upsertedCount) return notification;
            await trimSeen(recipient);
            try {
                getNotificationNamespace().to(String(recipient)).emit("notification:new", notification.toObject());
            } catch { /* socket delivery is best effort; MongoDB is the source of truth */ }
            return notification;
        }
        const notification = await Notification.create({ recipient, actor, type, payload });
        await trimSeen(recipient);
        try {
            getNotificationNamespace().to(String(recipient)).emit("notification:new", notification.toObject());
        } catch { /* socket delivery is best effort; MongoDB is the source of truth */ }
        return notification;
    },
    async removeFriendRequest(recipient, actor) {
        const notifications = await Notification.find({
            recipient,
            actor,
            type: "friend_request"
        }).select("_id").lean();
        if (!notifications.length) return;
        await Notification.deleteMany({ _id: { $in: notifications.map(({ _id }) => _id) } });
        try {
            const namespace = getNotificationNamespace();
            for (const { _id } of notifications) {
                namespace.to(String(recipient)).emit("notification:deleted", String(_id));
            }
        } catch { /* socket delivery is best effort; MongoDB is the source of truth */ }
    },
    async list(recipient) {
        const items = await Notification.find({ recipient }).sort({ createdAt: -1 }).limit(100).lean();
        const chatSenders = new Set();
        const deduplicated = items.filter((item) => {
            if (item.type !== "friend_chat") return true;
            const senderId = String(item.payload?.senderId || item.actor || "");
            if (!senderId || chatSenders.has(senderId)) return false;
            chatSenders.add(senderId);
            return true;
        });
        return Promise.all(deduplicated.map(async (item) => {
            if (item.type !== "friend_battle_request" || !item.payload?.requestId) return item;
            const active = await redis.exists(`battle:friend-request:${item.payload.requestId}`);
            if (active) return item;
            await Notification.updateOne({ _id: item._id, type: item.type }, {
                $set: { type: "friend_battle_abandoned", "payload.abandoned": true }
            });
            return { ...item, type: "friend_battle_abandoned", payload: { ...item.payload, abandoned: true } };
        }));
    },
    async markSeen(recipient, ids = null) {
        const filter = { recipient };
        if (Array.isArray(ids) && ids.length) filter._id = { $in: ids };
        await Notification.updateMany(filter, { $set: { seen: true, seenAt: new Date() } });
        await trimSeen(recipient);
        return { marked: true };
    },
    async clearChat(recipient, otherUserId) {
        await Notification.deleteMany({
            recipient,
            type: "friend_chat",
            "payload.senderId": String(otherUserId)
        });
    }
};



import { asyncHandler } from "../../middlewares/asyncHandler.middleware.js";
import { ApiResponse } from "../../utils/ApiResponse.js";
import { UserService } from "./user.service.js";
export const UserController = {
    me: asyncHandler(async (req, res) => res.json(new ApiResponse(200, await UserService.profile(req.user._id), "Profile loaded."))),
    publicProfile: asyncHandler(async (req, res) => res.json(new ApiResponse(200, await UserService.publicProfile(req.params.userId), "Profile loaded."))),
    friends: asyncHandler(async (req, res) => res.json(new ApiResponse(200, await UserService.friends(req.user._id), "Friends loaded."))),
    search: asyncHandler(async (req, res) => res.json(new ApiResponse(200, await UserService.search(req.user._id, req.body?.username), "Users found."))),
    update: asyncHandler(async (req, res) => res.json(new ApiResponse(200, await UserService.updateProfile(req.user._id, req.body, req.avatar), "Profile updated."))),
    request: asyncHandler(async (req, res) => res.status(201).json(new ApiResponse(201, await UserService.requestFriend(req.user._id, req.params.userId), "Friend request sent."))),
    respond: asyncHandler(async (req, res) => res.json(new ApiResponse(200, await UserService.respondFriend(req.user._id, req.params.userId, req.body.accept === true), "Friend request updated."))),
    remove: asyncHandler(async (req, res) => res.json(new ApiResponse(200, await UserService.unfriend(req.user._id, req.params.userId), "Friend removed.")))
};



import { Router } from "express";
import { authenticateUser } from "../../middlewares/auth.middleware.js";
import { handleAvatarUpload } from "../../middlewares/upload.middleware.js";
import { UserController } from "./user.controller.js";
export const userRouter = Router();
userRouter.use(authenticateUser);
userRouter.get("/me", UserController.me);
userRouter.get("/friends", UserController.friends);
userRouter.post("/search", UserController.search);
userRouter.patch("/me", handleAvatarUpload, UserController.update);
userRouter.get("/:userId/profile", UserController.publicProfile);
userRouter.post("/:userId/friend-request", UserController.request);
userRouter.post("/:userId/friend-response", UserController.respond);
userRouter.delete("/:userId/friend", UserController.remove);



import { User } from "../../models/user.model.js";
import mongoose from "mongoose";
import { ApiError } from "../../utils/ApiError.js";
import { NotificationService } from "../notification/notification.service.js";
import cloudinary from "../../config/cloudinary.js";
import { FRIEND_REQUEST_RESEND_COOLDOWN_MS } from "../../constants/user.constants.js";

const relation = (user, otherId) => user.friends.find((item) => String(item.user) === String(otherId));
const replaceFriendRelation = async (ownerId, otherId, requestedBy, status, updatedAt) => {
    await User.updateOne(
        { _id: ownerId },
        [{
            $set: {
                friends: {
                    $concatArrays: [
                        {
                            $filter: {
                                input: { $ifNull: ["$friends", []] },
                                as: "friend",
                                cond: { $ne: ["$$friend.user", otherId] }
                            }
                        },
                        [{ user: otherId, status, requestedBy, updatedAt }]
                    ]
                }
            }
        }],
        { updatePipeline: true }
    );
};

const ensureUser = async (id) => {
    if (!mongoose.isValidObjectId(id)) throw new ApiError(400, "User id is invalid.");
    const user = await User.findById(id).select("_id username email avatar profile friends");
    if (!user) throw new ApiError(404, "User not found.");
    return user;
};
const escapeRegex = (value) => value.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
const validProfile = ({ institution, bio, gender, education_level, education_year, education_stream }, currentLevel = "HSC") => {
    if (education_level !== undefined && !["SSC", "HSC", "SCHOOL"].includes(education_level)) throw new ApiError(400, "Invalid education level.");
    if (education_stream !== undefined && !["SCIENCE", "ARTS", "COMMERCE"].includes(education_stream)) throw new ApiError(400, "Invalid education stream.");
    const year = education_year === undefined ? undefined : Number(education_year);
    const max = (education_level || currentLevel) === "SCHOOL" ? 8 : 2;
    if (year !== undefined && (!Number.isInteger(year) || year < 1 || year > max)) throw new ApiError(400, "Invalid education year.");
    return Object.fromEntries(Object.entries({ institution, bio, gender, education_level, education_year: year, education_stream })
        .filter(([, value]) => value !== undefined));
};

export const UserService = {
    async profile(userId) { return ensureUser(userId); },
    async publicProfile(userId) {
        if (!mongoose.isValidObjectId(userId)) throw new ApiError(400, "User id is invalid.");
        const user = await User.findOne({ _id: userId, status: "ACTIVE" })
            .select("_id username avatar profile")
            .lean();
        if (!user) throw new ApiError(404, "User not found.");
        return user;
    },
    async friends(userId) {
        const user = await ensureUser(userId);
        const ids = user.friends.map((item) => item.user);
        const profiles = await User.find({ _id: { $in: ids } }).select("_id username avatar profile").lean();
        const byId = new Map(profiles.map((item) => [String(item._id), item]));
        return user.friends.map((item) => ({ ...item.toObject(), profile: byId.get(String(item.user)) || null }));
    },
    async search(userId, username) {
        if (typeof username !== "string" || !username.trim()) {
            throw new ApiError(400, "Username search text is required.");
        }
        const search = username.trim().toLowerCase();
        if (search.length > 50) throw new ApiError(400, "Username search text is too long.");
        return User.find({
            _id: { $ne: userId },
            username: { $regex: `^${escapeRegex(search)}` }
        })
            .select("_id username avatar profile")
            .sort({ username: 1 })
            .limit(20)
            .lean();
    },
    async updateProfile(userId, input, avatar) {
        const user = await ensureUser(userId);
        const updates = validProfile(input, user.profile?.education_level);
        if (input.education_level && input.education_level !== user.profile?.education_level && input.education_year === undefined) {
            updates.education_year = 1;
        }
        const previousAvatar = avatar ? user.avatar?.publicId : null;
        if (avatar) user.set("avatar", avatar);
        for (const [key, value] of Object.entries(updates)) {
            if (key !== "avatar") user.set(`profile.${key}`, value);
        }
        await user.save();
        if (previousAvatar) await cloudinary.uploader.destroy(previousAvatar, { resource_type: "image" });
        return user;
    },
    async requestFriend(userId, targetId) {
        if (String(userId) === String(targetId)) throw new ApiError(400, "You cannot add yourself.");
        const [user, target] = await Promise.all([ensureUser(userId), ensureUser(targetId)]);
        const existing = relation(user, targetId);
        if (existing?.status === "accepted") throw new ApiError(409, "You are already friends.");
        if (existing?.status === "requested") {
            const iAmRequester = String(existing.requestedBy) === String(userId);
            if (!iAmRequester) {
                throw new ApiError(409, "They already sent you a friend request. Accept it from Notifications.");
            }
            const elapsed = Date.now() - new Date(existing.updatedAt).getTime();
            if (elapsed < FRIEND_REQUEST_RESEND_COOLDOWN_MS) {
                const hoursRemaining = Math.ceil((FRIEND_REQUEST_RESEND_COOLDOWN_MS - elapsed) / (60 * 60 * 1000));
                throw new ApiError(429, `You can send a new request in ${hoursRemaining} hour(s).`);
            }
        }
        const now = new Date();
        await replaceFriendRelation(userId, target._id, user._id, "requested", now);
        await replaceFriendRelation(target._id, user._id, user._id, "requested", now);
        await NotificationService.removeFriendRequest(targetId, userId);
        await NotificationService.create({ recipient: targetId, actor: userId, type: "friend_request", payload: { username: user.username } });
        return { requested: true };
    },
    async respondFriend(userId, requesterId, accept) {
        const user = await ensureUser(userId);
        const item = relation(user, requesterId);
        if (!item || item.status !== "requested" || String(item.requestedBy) === String(userId)) throw new ApiError(404, "Friend request not found.");
        const status = accept ? "accepted" : "rejected";
        const now = new Date();
        await User.updateOne({ _id: userId, "friends.user": requesterId }, { $set: { "friends.$.status": status, "friends.$.updatedAt": now } });
        await User.updateOne({ _id: requesterId, "friends.user": userId }, { $set: { "friends.$.status": status, "friends.$.updatedAt": now } });
        await NotificationService.removeFriendRequest(userId, requesterId);
        await NotificationService.create({ recipient: requesterId, actor: userId, type: accept ? "friend_request_accepted" : "friend_request_rejected", payload: { username: user.username } });
        return { status };
    },
    async unfriend(userId, otherId) {
        await Promise.all([
            User.updateOne({ _id: userId }, { $pull: { friends: { user: otherId } } }),
            User.updateOne({ _id: otherId }, { $pull: { friends: { user: userId } } })
        ]);
        const { ChatService } = await import("../chat/chat.service.js");
        await ChatService.remove(userId, otherId);
        return { removed: true };
    },
    async isFriend(userId, otherId) {
        const user = await User.findOne({ _id: userId, friends: { $elemMatch: { user: otherId, status: "accepted" } } }).select("_id").lean();
        return Boolean(user);
    }
};
